1157	func (s *syncSession) replicateCanBootstrap(desiredRefs map[plumbing.ReferenceName]planner.DesiredRef) bool {
1158		for targetRef := range desiredRefs {
1159			if !s.target.refMap[targetRef].IsZero() {
1160				return false
1161			}
1162		}
1163		if !s.cfg.Prune {
1164			return true
1165		}
1166		for targetRef, hash := range s.target.refMap {
1167			if hash.IsZero() {
1168				continue
1169			}
1170			if _, ok := desiredRefs[targetRef]; ok {
1171				continue
1172			}
1173			if planner.IsRefExcluded(targetRef, s.cfg.ExcludeRefPrefixes, s.cfg.ExcludeRefs) {
1174				continue
1175			}
1176			// AllRefs overrides per-namespace allowlists: under "all refs" a
1177			// stale branch matters even when a Branches filter is set.
1178			branchScopeCovers := s.cfg.AllRefs || len(s.cfg.Branches) == 0
1179			switch {
1180			case targetRef.IsTag() && (s.cfg.IncludeTags || s.cfg.AllRefs):
1181				return false
1182			case targetRef.IsBranch() && len(s.cfg.Mappings) == 0 && branchScopeCovers:
1183				return false
1184			case s.cfg.AllRefs && planner.RefKindFromName(targetRef) == planner.RefKindOther && len(s.cfg.Mappings) == 0:
1185				return false
1186			}
1187		}
1188		return true
1189	}
