948		}
949		if len(desiredRefs) == 0 {
950			return Result{}, errors.New("no source refs matched")
951		}
952	
953		// Check for bootstrap opportunity (before allocating in-memory repo)
954		if ok, reason := planner.CanBootstrapRelay(s.cfg.ForceAny(), s.cfg.Prune, desiredRefs, targetRefMap); ok {
955			if s.cfg.DryRun {
956				plans, err := planner.BuildBootstrapPlans(desiredRefs, targetRefMap)
957				if err != nil {
