701	// tailPhaseLabel returns a phase label matching what's in plans.
702	func tailPhaseLabel(plans []planner.BranchPlan) string {
703		hasTag, hasOther := false, false
704		for _, plan := range plans {
705			switch plan.Kind {
706			case planner.RefKindTag:
707				hasTag = true
708			case planner.RefKindOther:
709				hasOther = true
710			case planner.RefKindBranch:
711			}
712		}
713		switch {
714		case hasTag && hasOther:
715			return "pushing tail refs"
716		case hasOther:
717			return "pushing other refs"
718		default:
719			return "pushing tags"
720		}
721	}
